function bankExecutionPage(){const cases=state.releases.filter(r=>r.assignedBankVerifierId===BANK_VERIFIER_ID&&r.status==='Approved in demo — awaiting simulated bank execution');return `${pageHead('Simulated release responses','Assigned demo execution requests · bank activity is a local simulation.')}${'<div class="callout" data-preserve-demo-copy>Simulated bank response — no live bank connection. Recording a result does not change a lien or move funds.</div>'}${cases.length?cases.map(r=>`<section class="panel"><h2>${esc(getFdr(r.fdrId)?.reference||r.fdrId)} · ${esc(r.id)}</h2><p>Checker: ${esc(r.checkerActor||'demo reviewer')} · Approved in demo; awaiting bank-side simulated confirmation.</p><button class="btn primary" data-action="bank-execute" data-id="${r.id}">Record simulated bank confirmation</button></section>`).join(''):'<section class="panel empty"><strong>No approved demo instructions</strong>Reviewer cases appear here only after clearances, maker recommendation, and a different demo checker identity.</section>'}`}
