function reconciliationPage(){const total=state.fdrs.reduce((s,f)=>s+f.amount,0),fresh=state.fdrs.filter(f=>f.lastConfirmed&&days(f.lastConfirmed)<=90&&f.verification==='Confirmed in demo data').reduce((s,f)=>s+f.amount,0),coverage=total?Math.round(fresh/total*100):0;const latest=new Map();for(const r of state.reconciliations)if(!latest.has(r.fdrId))latest.set(r.fdrId,r);return `${pageHead('Reconciliation & monitoring','Compare the portal register with a fixed demo bank-ledger fixture. No live polling.',role==='AICTE Officer'?'<button class="btn primary" data-action="run-reconciliation">Run reconciliation</button>':'')}<div class="callout">DEMO LEDGER · demo events include issued, renewed, not-extended, release-consent, and discharged examples. A feed entry is not a live bank connection.</div><div class="grid metrics"><div class="metric"><span>Verified value coverage</span><strong>${coverage}%</strong><small>${money(fresh)} freshly confirmed of ${money(total)} held · ≤90 days</small></div><div class="metric"><span>Portal instruments</span><strong>${state.fdrs.length}</strong><small>Fixed demo register</small></div><div class="metric"><span>Exceptions</span><strong>${[...latest.values()].filter(x=>x.issues.length).length}</strong><small>From latest reconciliation run</small></div></div><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>FDR</th><th>Portal amount / lien</th><th>demo ledger event</th><th>Comparison</th><th>Proof / freshness</th><th>Successor</th></tr></thead><tbody>${state.fdrs.map(f=>{const r=latest.get(f.id),doc=state.documents.find(d=>d.fdrId===f.id);return `<tr><td>${link(`/app/fdrs/${f.id}`,f.reference,'row-link')}</td><td>${money(f.amount)}<br>${esc(f.lien)}</td><td>${r?.event||'Not reconciled'}${r?.entryId?` · ${r.entryId}`:''}</td><td>${r?.issues.length?r.issues.map(x=>`<div>${status(x)}</div>`).join(''):'No run / no exception'}</td><td>${f.lastConfirmed?`Simulated bank confirmation · ${date(f.lastConfirmed)} · ${days(f.lastConfirmed)>90?'stale':'fresh'}`:'No bank confirmation'}<br><span class="small muted">Fingerprint ${doc?.hash?.slice(0,16)||'pending'}…</span></td><td>${f.successor?link(`/app/fdrs/${f.successor}`,getFdr(f.successor)?.reference||'successor','row-link'):'None'}</td></tr>`}).join('')}</tbody></table></div></section><section class="panel"><h2>demo ledger fixture</h2><p class="small muted">Entries: ${state.bankLedger.map(x=>`${x.event} ${getFdr(x.fdrId)?.reference||x.fdrId}`).join(' · ')}</p><p class="small">Coverage definition: value of instruments with a simulated “Confirmed in demo data” response dated within 90 days divided by total portal FDR value. It is a demo metric, not proof of active bank balance.</p></section>`}
