function policyAssistantAnswer(question){const q=question.toLowerCase();if(q.includes('1043')||q.includes('mismatch')||q.includes('flagged'))return {question,text:'FDR/26/1043 needs review because the institution declared ₹22,00,000 while the illustrative extraction shows ₹18,00,000. A bank confirmation request is still awaiting response, so PRAMAN does not choose either amount as authoritative.',refs:['FDR/26/1043','find-01','R-01 · v1.1'],next:'Inspect the source comparison and keep the finding open until independent evidence arrives.',path:'/app/fdrs/fdr-1043'};if(q.includes('1046')||q.includes('released')||q.includes('release'))return {question,text:'FDR/24/0610 is past its bank maturity date, but maturity does not create release eligibility. Its successor evidence review remains pending, and the release case stays blocked until the configured evidence and authorized decision gates are complete.',refs:['FDR/24/0610','rel-1046','R-03 · v1.0','R-04 · v1.0'],next:'Review the linked successor FDR and resolve the exact release blocker.',path:'/app/releases/rel-1046'};if(q.includes('attention')||q.includes('today')||q.includes('priority'))return {question,text:'The seeded control room has three open scrutiny findings, one pending bank response, two instruments within the 90-day maturity window, and two blocked release cases. The highest-value learning path starts with the FDR/26/1043 amount mismatch.',refs:['find-01','find-02','find-03','ver-2102','rel-1045','rel-1046'],next:'Open the judge fast track from Overview to move through the four critical queues.',path:'/app/overview'};if(q.includes('verify')||q.includes('genuine')||q.includes('proof'))return {question,text:'PRAMAN separates five trust states: institution-submitted, OCR-extracted, desk-checked, bank-confirmed, and reconciled. A fingerprint proves that the received copy has not changed; it does not prove bank issuance. Only identified, timely bank evidence can support the bank-confirmed state.',refs:['R-01 · v1.1','R-02 · v1.0','ver-2101'],next:'Inspect the verification passport and its fingerprint-bound response evidence.',path:'/app/verification'};return {question,text:'This prototype assistant only answers four seeded topics: the FDR/26/1043 mismatch, release readiness for FDR/24/0610, today’s attention queue, and how evidence becomes bank-confirmed. It will not invent a policy answer outside those fixtures.',refs:['Local prototype knowledge boundary'],next:'Choose a suggested question or route the matter to an authorized policy reviewer.',path:'/app/policy'}}
function policyPage(){const rules=state.policies||[];const answer=state.policyAnswer;const prompts=['Why is FDR/26/1043 flagged?','Can FDR/24/0610 be released?','What needs attention today?','What counts as bank-confirmed?'];return `${pageHead('Policy Copilot','Evidence-grounded, deterministic assistance for the judge demo.')}<div class="assistant-boundary"><strong>SIMULATED ASSISTANT</strong><span>Four hardcoded evidence-grounded responses · no external model · no legal or regulatory decision</span></div><div class="assistant-layout"><aside class="assistant-sources"><div class="panel-head"><h2>Available context</h2><span class="badge info">Local only</span></div><div class="source-stack"><div><span>01</span><strong>Case records</strong><small>Seeded FDRs, findings, verification events, and release blockers</small></div><div><span>02</span><strong>Prototype rules</strong><small>Versioned local controls R-01 through R-04</small></div><div><span>03</span><strong>Evidence links</strong><small>Document fingerprints, actors, timestamps, and record IDs</small></div></div><p class="small muted">The assistant cannot access live AICTE policy, bank systems, uploaded files, or the internet.</p></aside><section class="assistant-chat" aria-label="Mock policy assistant conversation"><div class="assistant-header"><div><span class="assistant-avatar" aria-hidden="true">P</span><div><strong>PRAMAN Copilot</strong><small>Evidence assistant · simulated</small></div></div><span class="assistant-status"><i></i> Local fixture</span></div><div class="assistant-thread" aria-live="polite"><div class="chat-message assistant"><span class="assistant-avatar" aria-hidden="true">P</span><div><strong>How can I help with this review?</strong><p>I can explain a seeded discrepancy, release blocker, attention queue, or verification state—and cite the exact local records used.</p></div></div>${answer?`<div class="chat-message user"><div><p>${esc(answer.question||'Case question')}</p></div></div><div class="chat-message assistant"><span class="assistant-avatar" aria-hidden="true">P</span><div><p>${esc(answer.text)}</p><div class="chat-citations">${answer.refs.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="chat-next"><small>NEXT SAFE ACTION</small><p>${esc(answer.next)}</p>${link(answer.path,'Open supporting record →','text-link')}</div></div></div>`:''}</div><div class="suggestion-chips" aria-label="Suggested questions">${prompts.map(prompt=>`<button type="button" data-action="chat-prompt" data-prompt="${esc(prompt)}">${esc(prompt)}</button>`).join('')}</div><form id="policy-assistant" class="assistant-composer"><label class="sr-only" for="copilot-question">Ask the simulated policy assistant</label><input id="copilot-question" name="question" placeholder="Ask about a seeded case or evidence state" required autocomplete="off"><button class="btn primary">Ask <span aria-hidden="true">↑</span></button></form><p class="assistant-note">Draft guidance only. An authorized official remains responsible for every regulatory decision.</p></section></div><section class="panel flush rule-register"><div class="panel-head"><div><h2>Versioned rule register</h2><p class="small muted">Prototype controls and scenario data—not legal advice.</p></div><span class="mono small">ACTIVE FIXTURE ${esc(state.policyVersion||'1.1')}</span></div><div class="table-wrap"><table><thead><tr><th>Rule / version</th><th>Source class</th><th>Effective date</th><th>Plain-language behavior</th><th>Missing-data outcome</th></tr></thead><tbody>${rules.map(r=>`<tr><td><strong>${esc(r.name)}</strong><br><span class="mono">${r.id} · v${r.version}</span></td><td>${esc(r.source)}</td><td>${esc(r.effective)}</td><td>${esc(r.summary)}<br><span class="small muted">Checks: ${esc(r.fields)}</span></td><td>${esc(r.missing)}</td></tr>`).join('')}</tbody></table></div></section>`}
function settingsPage(){return `${pageHead('Settings & Demo Controls','Control the local demo environment and inspect its boundaries.')}
<div class="two-col"><section class="panel"><div class="panel-head"><h2>Current demo session</h2></div><div class="field-list"><div class="field-row"><span>Selected role</span><strong>${esc(role)}</strong></div><div class="field-row"><span>Environment</span><strong>DEMO ENVIRONMENT</strong></div><div class="field-row"><span>Persistence</span><strong>Browser localStorage when available</strong></div><div class="field-row"><span>Demo date</span><strong>${date(DEMO_DATE)}</strong></div></div>${role==='AICTE Officer'?'<div class="action-row"><button class="btn danger" data-action="reset-confirm">Reset demo data</button></div>':'<p class="small muted">Reset controls are limited to the AICTE Officer role.</p>'}</section>
<section class="panel"><div class="panel-head"><h2>Simulation boundaries</h2></div><div class="field-list">${['No bank or AICTE network connection','No document upload leaves this browser','Extraction is illustrative and deterministic','Role switch is not authentication or secure RBAC','No lien change, release instruction, or funds transfer','Browser history is not a production audit record'].map(x=>`<div class="field-row"><span>• ${esc(x)}</span></div>`).join('')}</div><p class="small muted">If browser storage is unavailable or malformed, the app falls back to seed data for the current session.</p></section></div>`}
function landing(){return `<div class="landing"><nav class="landing-nav"><a class="brand" href="/" data-nav="/"><picture class="brand-image"><source type="image/webp" srcset="/Coral%20Geometric%20P%20Emblem.webp"><img class="brand-logo" src="/Coral%20Geometric%20P%20Emblem.png" alt="" aria-hidden="true"></picture>Praman</a><div class="landing-nav-actions"><a href="#how-it-works" class="btn quiet">How it works</a><a href="/login" data-nav="/login" class="btn">Log In / Sign Up</a></div></nav><main><section class="hero"><div class="hero-copy"><div class="eyebrow">AICTE · SECURITY DEPOSIT MANAGEMENT</div><h1><span>Security deposits.</span><span>Verified with evidence.</span></h1><p>A unified platform for FDR scrutiny, bank verification, maturity monitoring, and accountable release workflows.</p><div class="hero-ctas"><a class="btn primary" href="/login" data-nav="/login">Explore the platform <span aria-hidden="true">→</span></a><a class="btn" href="#how-it-works">View verification workflow</a></div></div><div class="hero-art" aria-hidden="true"><picture><source type="image/webp" srcset="/Circular%20Finance%20Dashboard%20Infographic.webp"><img src="/Circular%20Finance%20Dashboard%20Infographic.png" alt="" draggable="false"></picture></div></section>
<section class="landing-section" id="how-it-works"><div class="eyebrow">A CLEAR RECORD AT EVERY STEP</div><h2>From submission to release review</h2><p class="section-intro">Each state is tied to its source, owner, and next action. Independent confirmation remains distinct from document extraction and reviewer judgement.</p><div class="steps" role="list" aria-label="Five steps in the FDR review lifecycle">${[['01','Submit','Institution records FDR details and supporting evidence.'],['02','Scrutinize','Reviewers compare fields and resolve explainable flags.'],['03','Confirm','A simulated bank-side role returns a demo response.'],['04','Monitor','Track maturity, renewal, replacement, and freshness.'],['05','Release review','Record clearances and a separate checker decision.']].map(x=>`<div class="step" role="listitem"><span class="step-num" aria-hidden="true">${x[0]}</span><strong>${x[1]}</strong><p>${x[2]}</p></div>`).join('')}</div></section>
<section class="landing-section landing-features"><div class="eyebrow">DESIGNED FOR EVIDENCE-LINKED OPERATIONS</div><div class="feature-grid">${[['Evidence-linked scrutiny','Compare submitted, extracted, and simulated response values with their provenance.'],['Bank confirmation workflow','Create a request and record a clearly labelled demo response.'],['Lifecycle monitoring','See upcoming maturity and successor relationships without implying release.'],['Accountable release review','Inspect scenario clearances, blockers, and maker–checker steps.']].map(x=>`<div class="feature"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section>${landingExtension()}</main><footer class="landing-footer"><span>Praman · AICTE Security Deposit Management · prototype</span><span>DEMO ENVIRONMENT</span></footer></div>`}
function landingExtension(){return `<div class="landing-extension">
<section class="landing-section landing-evidence" aria-labelledby="evidence-integrity-title" data-landing-reveal>
  <div class="landing-section-heading"><div><div class="eyebrow">EVIDENCE INTEGRITY</div><h2 id="evidence-integrity-title">Know what was submitted. Know what was confirmed.</h2></div><p class="section-intro">Each statement keeps its source visible, so a document, an extraction, a reviewer assessment, and an external confirmation remain distinct.</p></div>
  <figure class="evidence-map" aria-labelledby="evidence-map-caption"><svg viewBox="0 0 1000 470" role="img" aria-labelledby="evidence-svg-title evidence-svg-desc" preserveAspectRatio="xMidYMid meet"><title id="evidence-svg-title">Evidence relationships for FDR FDR/26/1043</title><desc id="evidence-svg-desc">An FDR record connects to its submitted document and fingerprint history, extracted fields, simulated bank confirmation, reviewer findings, replacement instrument, and audit history.</desc>
    <g class="map-links" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M500 228 245 100M500 228 500 88M500 228 755 100M500 248 245 370M500 248 500 390M500 248 725 370M500 248 890 370"/><path d="M245 100 500 88M500 88 755 100M245 370 500 390" stroke-dasharray="4 6" opacity=".5"/></g>
    <g class="map-node map-submitted"><rect x="70" y="45" width="250" height="112" rx="7"/><text x="92" y="78" class="map-kicker">SUBMITTED</text><text x="92" y="106" class="map-title">FDR document</text><text x="92" y="132" class="map-copy">Original file · version 01</text></g>
    <g class="map-node map-extracted"><rect x="375" y="28" width="250" height="112" rx="7"/><text x="397" y="61" class="map-kicker">DOCUMENT HISTORY</text><text x="397" y="89" class="map-title">Fingerprint & versions</text><text x="397" y="115" class="map-copy">Copy-change comparison</text></g>
    <g class="map-node map-extracted"><rect x="680" y="45" width="250" height="112" rx="7"/><text x="702" y="78" class="map-kicker">EXTRACTED</text><text x="702" y="106" class="map-title">Declared fields</text><text x="702" y="132" class="map-copy">Amount · holder · maturity</text></g>
    <g class="map-center"><circle cx="500" cy="238" r="78"/><circle cx="500" cy="238" r="66"/><text x="500" y="226" text-anchor="middle" class="map-kicker">FDR RECORD</text><text x="500" y="252" text-anchor="middle" class="map-title">FDR/26/1043</text><text x="500" y="274" text-anchor="middle" class="map-copy">Evidence-linked case</text></g>
    <g class="map-node map-review"><rect x="70" y="316" width="250" height="112" rx="7"/><text x="92" y="349" class="map-kicker">REVIEWER-ASSESSED</text><text x="92" y="377" class="map-title">Scrutiny findings</text><text x="92" y="403" class="map-copy">Explainable flags & decisions</text></g>
    <g class="map-node map-bank"><rect x="375" y="344" width="250" height="112" rx="7"/><text x="397" y="377" class="map-kicker">SIMULATED BANK CONFIRMATION</text><text x="397" y="405" class="map-title">Independent response</text><text x="397" y="431" class="map-copy">Source and response date recorded</text></g>
    <g class="map-node map-review map-compact"><rect x="655" y="344" width="140" height="94" rx="7"/><text x="670" y="373" class="map-kicker">SUCCESSOR</text><text x="670" y="399" class="map-title">Replacement FDR</text><text x="670" y="420" class="map-copy">Linked instrument</text></g>
    <g class="map-node map-review map-compact"><rect x="820" y="344" width="140" height="94" rx="7"/><text x="835" y="373" class="map-kicker">TRACEABILITY</text><text x="835" y="399" class="map-title">Audit history</text><text x="835" y="420" class="map-copy">Actor · action · time</text></g>
  </svg><figcaption id="evidence-map-caption"><span><i class="legend-mark submitted"></i>Submitted evidence</span><span><i class="legend-mark extracted"></i>Extracted data</span><span><i class="legend-mark reviewed"></i>Reviewer assessment</span><span><i class="legend-mark confirmed"></i>Simulated bank confirmation</span></figcaption></figure>
</section>
<section class="landing-section landing-monitoring" aria-labelledby="monitoring-title" data-landing-reveal><div class="landing-section-heading"><div><div class="eyebrow">CONTINUOUS MONITORING</div><h2 id="monitoring-title">An accepted FDR still needs attention.</h2></div><p class="section-intro">A record moves through dated checks over its life. A later comparison can surface a change that needs review.</p></div>
  <div class="monitoring-layout"><ol class="monitoring-timeline"><li><span class="monitor-dot"></span><time>ISSUE</time><strong>Initial confirmation</strong><p>Instrument details and evidence are recorded.</p></li><li><span class="monitor-dot"></span><time>PERIODIC</time><strong>Reconciliation</strong><p>Recorded details are compared with the latest available evidence.</p></li><li class="monitor-alert"><span class="monitor-dot"></span><time>RENEWAL</time><strong>Renewal check due</strong><p>No successor evidence is linked after the recorded maturity date.</p></li><li><span class="monitor-dot"></span><time>FRESHNESS</time><strong>Confirmation ages</strong><p>Reviewers can identify when another confirmation is needed.</p></li><li><span class="monitor-dot"></span><time>MATURITY</time><strong>Maturity alert</strong><p>Upcoming dates route the record for follow-up.</p></li></ol><aside class="monitoring-example" data-preserve-synthetic><div class="example-label">SYNTHETIC EXAMPLE · FDR/26/1043</div><div class="example-rule"></div><p class="example-finding">Renewal missing</p><p>A later reconciliation found no successor evidence linked to the matured instrument.</p><small>Illustrative record comparison; no real-time bank access is shown.</small></aside></div>
</section>
<section class="landing-section landing-release" aria-labelledby="release-title" data-landing-reveal><div class="landing-section-heading"><div><div class="eyebrow">CONTROLLED RELEASE</div><h2 id="release-title">Three clocks. One accountable decision.</h2></div><p class="section-intro">Maturity, the applicable holding period, and release eligibility are tracked separately before a case can progress.</p></div>
  <div class="release-visual"><p class="release-caption">Illustrative sequence · actual dates and gates depend on the case</p><div class="release-clocks"><div class="clock-track"><span class="clock-name">Bank maturity</span><div class="clock-line"><i style="--clock-progress:100%"></i><b class="clock-pin end"></b></div><span class="clock-date">Matured</span></div><div class="clock-track"><span class="clock-name">Regulatory holding period</span><div class="clock-line"><i style="--clock-progress:72%"></i><b class="clock-pin current"></b></div><span class="clock-date">In progress</span></div><div class="clock-track"><span class="clock-name">Release eligibility</span><div class="clock-line"><i style="--clock-progress:28%"></i><b class="clock-pin current"></b></div><span class="clock-date">Clearances pending</span></div></div><div class="release-gates"><div class="release-gate complete"><span class="gate-index">01</span><strong>Clearance gates</strong><small>Required findings resolved</small></div><div class="release-gate"><span class="gate-index">02</span><strong>Maker review</strong><small>Recommendation recorded</small></div><div class="release-gate"><span class="gate-index">03</span><strong>Checker approval</strong><small>Independent decision</small></div><div class="release-gate simulated"><span class="gate-index">04</span><strong>Bank confirmation</strong><small>Simulated response before resolution</small></div></div><p class="release-note"><strong>Maturity alone does not authorize release.</strong> Each required clearance and approval remains a separate decision.</p></div>
</section>
<section class="landing-closing" aria-labelledby="closing-title" data-landing-reveal><div class="closing-rule" aria-hidden="true"></div><div class="closing-copy"><h2 id="closing-title">A clearer record at every step.</h2><p>Explore how evidence, independent confirmation and accountable release workflows fit together.</p></div><a class="btn primary" href="/login" data-nav="/login">Explore the platform <span aria-hidden="true">→</span></a></section>
</div>`}
function landing(){return `<div class="landing scientific-landing"><nav class="landing-nav"><a class="brand" href="/" data-nav="/" aria-label="Praman home"><span class="praman-glyph" aria-hidden="true">P</span><span>PRAMAN</span></a><div class="landing-nav-links"><a href="#workflow">Workflow</a><a href="#capabilities">Capabilities</a><a href="#architecture">Evidence model</a></div><div class="landing-nav-actions"><a href="/demo" data-nav="/demo" class="btn quiet">Switch role</a><a href="/app/overview" data-nav="/app/overview" class="btn primary">Open judge demo <span aria-hidden="true">→</span></a></div></nav><main><section class="hero scientific-hero"><div class="hero-copy"><div class="prototype-flag"><span></span>SMART INDIA HACKATHON 2026 · INTERACTIVE PROTOTYPE</div><h1>Every security deposit.<br><em>One defensible evidence trail.</em></h1><p>PRAMAN connects FDR submission, explainable scrutiny, authorized bank confirmation, continuous maturity monitoring, and controlled release—without confusing a document match with proof.</p><div class="hero-ctas"><a class="btn primary" href="/app/overview" data-nav="/app/overview">Enter AICTE workspace <span aria-hidden="true">→</span></a><a class="btn hero-secondary" href="#judge-path">See the 3-minute path</a></div><div class="hero-facts" aria-label="Core system model"><div><strong>02</strong><span>Connected portals</span></div><div><strong>05</strong><span>Evidence states</span></div><div><strong>03</strong><span>Independent clocks</span></div></div><p class="hero-disclosure">Demo environment · synthetic records · simulated bank responses · no live AICTE or bank connection</p></div><div class="hero-console" aria-label="Seeded FDR verification passport preview"><div class="console-top"><span>VERIFICATION PASSPORT</span><span class="console-live"><i></i> SEEDED CASE</span></div><div class="console-id"><div><small>INSTRUMENT</small><strong>FDR/26/1043</strong><span>Kaveri College of Engineering</span></div><span class="badge warn">Needs review</span></div><div class="console-amount"><small>PRINCIPAL UNDER REVIEW</small><strong>₹18,00,000</strong><span>Declared value ₹22,00,000</span></div><div class="console-compare"><div><span>Institution submitted</span><strong>₹22,00,000</strong><small>01 Dec 2025</small></div><div class="compare-arrow" aria-hidden="true">≠</div><div><span>OCR extracted</span><strong>₹18,00,000</strong><small>Sample document · p.1</small></div></div><ol class="console-evidence"><li class="done"><span>01</span><strong>Submitted</strong><small>Source retained</small></li><li class="done"><span>02</span><strong>Extracted</strong><small>Illustrative OCR</small></li><li class="active"><span>03</span><strong>Desk review</strong><small>Mismatch open</small></li><li><span>04</span><strong>Bank response</strong><small>Awaiting</small></li><li><span>05</span><strong>Reconcile</strong><small>Not current</small></li></ol><a href="/app/fdrs/fdr-1043" data-nav="/app/fdrs/fdr-1043" class="console-action">Inspect linked evidence <span aria-hidden="true">↗</span></a></div></section>
<section class="judge-showcase" id="judge-path"><div class="section-index">01 · JUDGE PATH</div><div class="showcase-heading"><h2>Understand the whole system<br>by using four real flows.</h2><p>No login. No setup. Each checkpoint opens a working, deterministic scenario with recoverable state.</p></div><div class="judge-cards"><a href="/app/fdrs/fdr-1043" data-nav="/app/fdrs/fdr-1043"><span>01</span><small>SCRUTINY</small><h3>Find the exact mismatch</h3><p>Compare institution-submitted, extracted, and simulated bank-side values with provenance.</p><b>Open passport →</b></a><a href="/app/verification" data-nav="/app/verification"><span>02</span><small>CONFIRMATION</small><h3>Request independent evidence</h3><p>See a single-use, fingerprint-bound verification request and restricted bank response view.</p><b>Open queue →</b></a><a href="/app/maturities" data-nav="/app/maturities"><span>03</span><small>CONTINUITY</small><h3>Protect the deposit lifecycle</h3><p>Separate bank maturity, policy holding period, renewal evidence, and release eligibility.</p><b>Open monitoring →</b></a><a href="/app/releases/rel-1045" data-nav="/app/releases/rel-1045"><span>04</span><small>CONTROLLED RELEASE</small><h3>Explain every blocker</h3><p>Inspect case-specific clearances, maker–checker separation, and bank execution evidence.</p><b>Open release case →</b></a></div></section>
<section class="landing-section system-workflow" id="workflow"><div class="section-index">02 · END-TO-END WORKFLOW</div><div class="landing-section-heading"><div><h2>One lifecycle. Explicit trust boundaries.</h2></div><p class="section-intro">PRAMAN is not an upload portal. It preserves who asserted each fact, what evidence supports it, and which authority can act next.</p></div><div class="system-steps">${[['01','Submit','Institution metadata + original evidence'],['02','Extract','OCR draft + field confidence'],['03','Scrutinize','Rules + human disposition'],['04','Confirm','Authorized bank evidence'],['05','Monitor','Maturity + renewal + freshness'],['06','Release','Clearances + maker–checker']].map(([n,title,copy])=>`<div><span>${n}</span><strong>${title}</strong><small>${copy}</small></div>`).join('')}</div></section>
<section class="capability-ledger" id="capabilities"><div class="capability-intro"><div class="section-index">03 · WHAT THE PROTOTYPE PROVES</div><h2>Built around decisions,<br>not decorative dashboards.</h2><p>Every interface answers three questions: what is true now, what evidence supports it, and who owns the next action.</p><a href="/app/overview" data-nav="/app/overview" class="text-link">Explore all working screens →</a></div><div class="capability-list">${[['Evidence passport','Document versions, fingerprints, field provenance, findings, bank responses, and release records stay linked.','/app/fdrs/fdr-1043'],['Explainable scrutiny','Concrete differences create review flags; no opaque AI score and no automatic fraud claim.','/app/scrutiny'],['Bank-aware verification','A restricted verifier handles assigned requests; responses preserve source, time, fields, and evidence.','/app/verification'],['Continuous protection','Reconciliation surfaces stale confirmation, renewal gaps, lien changes, and successor relationships.','/app/reconciliation'],['Policy-aware assistance','Versioned rules explain blockers and draft next steps while officials retain decision authority.','/app/policy'],['Accountable release','Maturity never auto-releases an FDR; case-specific gates and maker–checker review remain explicit.','/app/releases']].map(([title,copy,path],i)=>`<a href="${path}" data-nav="${path}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${title}</strong><p>${copy}</p></div><b aria-hidden="true">↗</b></a>`).join('')}</div></section>
<div id="architecture">${landingExtension()}</div></main><footer class="landing-footer"><div><strong>PRAMAN</strong><span>Proposed AICTE Security Deposit & FDR Management System</span></div><div><span>Smart India Hackathon 2026 prototype</span><span>All records are synthetic</span></div></footer></div>`}
function demoEntry(){return `<div class="demo-entry"><header class="demo-header"><a class="brand" href="/" data-nav="/"><span class="praman-glyph" aria-hidden="true">P</span>PRAMAN</a><a class="btn" href="/app/overview" data-nav="/app/overview">Skip to judge workspace →</a></header><main class="demo-entry-body"><div class="eyebrow" data-preserve-demo-copy>DEMO ROLE SELECTOR · SYNTHETIC DATA</div><h1>Choose a perspective</h1><p class="muted">No credentials are required. Switch perspectives at any time without losing the current demo state.</p><form id="role-entry"><div class="role-grid">${[['Institution User','Institution Portal','Submit evidence, resolve deficiencies, and follow an FDR through its lifecycle.'],['Regional Officer','Regional Review','Triage regional cases, discrepancies, verification requests, and maturity risk.'],['AICTE Officer','AICTE Control Room','See the full system: scrutiny, verification, reconciliation, policy, release, and audit.'],['Bank Verifier','Restricted Bank View','Review only assigned requests and return a simulated evidence-backed response.']].map(([value,label,description])=>`<label class="role-option"><input type="radio" name="role" value="${value}" ${value===role?'checked':''}><span class="role-number">${String(ROLE_OPTIONS.indexOf(value)+1).padStart(2,'0')}</span><strong>${label}</strong><p>${description}</p></label>`).join('')}</div><div class="action-row"><button class="btn primary">Enter selected workspace →</button><a class="btn quiet" href="/" data-nav="/">Return to product story</a></div></form></main></div>`}
