function wizard(){if(role==='Bank Verifier')return `${pageHead('Submission unavailable','Bank Verifier cannot submit institution records.')}${link('/app/overview','Return to overview','btn')}`;if(wizardStep<1||wizardStep>6)wizardStep=1;const val=(k,def='')=>esc(wizardData[k]??def);let body='';
if(wizardStep===1)body=`<div class="form-grid"><div class="form-field"><label for="institution">Institution name</label><input id="institution" name="institution" value="${val('institution','Aarohan Institute of Technology')}" required></div><div class="form-field"><label for="programme">Programme / institution type</label><input id="programme" name="programme" value="${val('programme','Engineering')}" required></div><div class="form-field"><label for="region">Region</label><input id="region" name="region" value="${val('region','Maharashtra')}"></div><div class="form-field"><label for="contact">Contact role</label><input id="contact" name="contact" value="${val('contact','Institution nodal officer')}"></div></div>`;
if(wizardStep===2)body=`<div class="form-grid"><div class="form-field"><label for="reference">FDR reference</label><input id="reference" name="reference" placeholder="FDR/26/1201" value="${val('reference')}" required></div><div class="form-field"><label for="amount">Principal amount (₹)</label><input id="amount" name="amount" type="number" min="1" value="${val('amount','2500000')}" required></div><div class="form-field"><label for="bank">Bank name</label><input id="bank" name="bank" value="${val('bank','State Bank of Deccan')}" required></div><div class="form-field"><label for="branch">Branch</label><input id="branch" name="branch" value="${val('branch','Pune Education Branch')}" required></div><div class="form-field"><label for="issue">Issue date</label><input id="issue" name="issue" type="date" value="${val('issue',DEMO_DATE)}" required></div><div class="form-field"><label for="maturity">Maturity date</label><input id="maturity" name="maturity" type="date" value="${val('maturity','2028-10-25')}" required></div><div class="form-field wide"><label for="lien">Declared lien holder</label><input id="lien" name="lien" value="${val('lien','AICTE — Security Deposit')}" required></div></div>`;
if(wizardStep===2)body+=`<div class="form-grid" style="margin-top:12px"><div class="form-field"><label for="holder">FDR holder</label><input id="holder" name="holder" value="${val('holder',wizardData.institution||'Aarohan Institute of Technology')}" required></div><div class="form-field"><label for="ifsc">IFSC (demo format)</label><input id="ifsc" name="ifsc" value="${val('ifsc','SBDK0000421')}" required></div></div>`;
if(wizardStep===3)body=`<div class="form-field"><label>Choose a document</label><input type="file" accept=".pdf,.png,.jpg,.jpeg" name="document" aria-describedby="upload-note"><span class="small muted" id="upload-note">PDF, PNG, or JPG · selected files remain in this browser and are not uploaded.</span>${wizardData.documentName?`<span class="badge info">Selected locally: ${esc(wizardData.documentName)}</span>`:''}</div><div class="action-row"><button type="button" class="btn" data-action="sample-document">Use demo sample document</button>${wizardData.sample?' <span class="badge good">SAMPLE / DEMO selected</span>':''}</div><div class="callout">No OCR service is connected. The next step shows deterministic illustrative extraction fields only.</div>`;
if(wizardStep===4)body=`<div class="notice">Illustrative extraction · not bank verification. Review the declared amount and the demo sample value below before continuing.</div><div class="form-grid" style="margin-top:14px"><div class="form-field"><label>Institution-declared amount (₹)</label><input disabled value="${val('declaredAmount',wizardData.amount||'')}" aria-label="Institution declared amount"></div><div class="form-field"><label for="extractedAmount">Illustrative extracted amount (₹)</label><input id="extractedAmount" name="extractedAmount" type="number" min="1" value="${val('extractedAmount',wizardData.amount||'')}" required></div><div class="form-field"><label>Extracted FDR reference</label><input disabled value="${val('reference')}"></div><div class="form-field"><label>Source</label><input disabled value="Sample document · illustrative extraction"></div></div>`;
if(wizardStep===5){const amountMismatch=Number(wizardData.amount)!==Number(wizardData.extractedAmount||wizardData.amount);const lienMissing=!wizardData.lien||wizardData.lien.length<3;body=`<div class="panel" style="background:var(--muted)"><h2>Pre-submission checks</h2><div class="field-list"><div class="field-row"><span>Required institution and instrument fields</span>${badge('Complete','good')}</div><div class="field-row"><span>Document source</span>${wizardData.sample?badge('demo sample selected','info'):badge('No sample selected','warn')}</div><div class="field-row"><span>Declared vs illustrative amount</span>${amountMismatch?badge(`Mismatch · ${money(Number(wizardData.amount))} vs ${money(Number(wizardData.extractedAmount))}`,'warn'):badge('Values align in demo','good')}</div><div class="field-row"><span>Lien declaration</span>${lienMissing?badge('Needs clarification','warn'):badge('Provided · not independently validated','info')}</div></div></div><div class="callout">These checks help route human review. The extraction and matching values do not authenticate the instrument or its issuer.</div>`}
if(wizardStep===5){const duplicate=state.fdrs.find(f=>f.reference.toLowerCase()===(wizardData.reference||'').toLowerCase()),ifscOk=/^[A-Z]{4}0[A-Z0-9]{6}$/.test(wizardData.ifsc||'DEMO0000100'),bankOk=['State Bank of Deccan','Western Coast Bank','National Mercantile Bank','Deccan Cooperative Bank'].includes(wizardData.bank);body+=`<section class="panel"><h2>Additional validation report</h2><div class="field-list"><div class="field-row"><span>Unique FDR number</span>${duplicate?badge(`Duplicate · ${duplicate.reference}`,'bad'):badge('No duplicate in current demo register','good')}</div><div class="field-row"><span>IFSC format</span>${ifscOk?badge('demo format accepted','good'):badge('Review required','warn')}</div><div class="field-row"><span>Issuing bank eligibility</span>${bankOk?badge('Included in demo sample list','info'):badge('Not in demo sample list · reviewer confirmation needed','warn')}</div><div class="field-row"><span>Maturity vs issue date</span>${wizardData.maturity>wizardData.issue?badge('Maturity follows issue date','good'):badge('Invalid date order','bad')}</div><div class="field-row"><span>Data provenance</span><span>Submitted by institution · illustrative extraction ${date(DEMO_DATE)} · no simulated bank response yet</span></div></div><p class="small muted">Format and sample-list checks are demo routing signals, not a finding about real bank eligibility.</p></section>`}
if(wizardStep===6)body=`<div class="notice"><strong>Ready to submit to demo scrutiny.</strong><br>${esc(wizardData.reference||'New FDR')} · ${esc(wizardData.institution||'Institution')} · ${money(Number(wizardData.amount)||0)}<br><span class="small">The record will be added to this browser's demo register and audit history.</span></div>`;
return `${link('/app/overview','← Cancel submission','backlink')}${pageHead('Submit an FDR',`Institution-side intake · ${role}`)}<section class="panel"><div class="stepper">${WIZARD_NAMES.map((x,i)=>`<div class="wizard-step ${i+1===wizardStep?'current':i+1<wizardStep?'complete':''}">${i+1}. ${x}</div>`).join('')}</div><form id="wizard-form" novalidate><div id="wizard-error" class="small" style="color:var(--destructive);margin-bottom:10px"></div>${body}<div class="wizard-foot">${wizardStep>1?'<button type="button" class="btn" data-action="wizard-prev">← Previous</button>':'<span></span>'}${wizardStep<6?'<button type="submit" class="btn primary">Continue →</button>':'<button type="button" class="btn primary" data-action="wizard-submit">Submit to scrutiny</button>'}</div></form></section>`}
function floatingAssistantAnswer(key){const records=visibleFdrs(),open=state.findings.filter(f=>findingNeedsReview(f)&&records.some(record=>record.id===f.fdrId)).length,pending=state.verifications.filter(v=>v.status==='Awaiting bank response'&&records.some(record=>record.id===v.fdrId)).length,urgent=records.filter(f=>days(f.maturity)<=90&&!f.renewed).length;if(key==='attention')return {question:'What needs my attention?',answer:`${open} scrutiny findings, ${pending} pending bank response, and ${urgent} time-critical instruments need attention in this workspace. Start with the ₹4,00,000 amount mismatch on FDR/26/1043.`,path:'/app/overview',action:'Open attention queue'};if(key==='mismatch')return {question:'Why is FDR/26/1043 flagged?',answer:'The institution submitted ₹22,00,000, while the illustrative extraction shows ₹18,00,000. PRAMAN keeps both values visible and waits for independent evidence instead of choosing one automatically.',path:'/app/fdrs/fdr-1043',action:'Inspect evidence passport'};return {question:'Can FDR/24/0610 be released?',answer:'Not yet. Its bank maturity has passed, but successor evidence review is still pending. Maturity, policy eligibility, and the authorized release decision remain separate gates.',path:'/app/releases/rel-1046',action:'Review release blockers'}}
function floatingAssistant(){const choices=[['attention','What needs my attention?'],['mismatch','Why is FDR/26/1043 flagged?'],['release','Can FDR/24/0610 be released?']],answer=assistantAnswerKey?floatingAssistantAnswer(assistantAnswerKey):null;return `<div class="floating-assistant ${assistantOpen?'is-open':''}">${assistantOpen?`<section class="assistant-float-panel" id="assistant-panel" role="dialog" aria-label="PRAMAN assistant"><header><div><span class="assistant-avatar" aria-hidden="true">P</span><span><strong>PRAMAN Assistant</strong><small>Case-aware sample responses</small></span></div><button type="button" class="assistant-close" data-action="assistant-close" aria-label="Close PRAMAN assistant">×</button></header><div class="assistant-float-body" aria-live="polite"><div class="assistant-float-message"><span class="assistant-avatar" aria-hidden="true">P</span><p>Choose a question and I’ll explain the linked case evidence.</p></div>${answer?`<div class="assistant-user-message">${esc(answer.question)}</div><div class="assistant-float-message"><span class="assistant-avatar" aria-hidden="true">P</span><div><p>${esc(answer.answer)}</p>${link(answer.path,`${esc(answer.action)} →`,'assistant-source-link')}</div></div>`:''}</div><div class="assistant-choices">${choices.map(([key,label])=>`<button type="button" data-action="assistant-choice" data-choice="${key}" class="${assistantAnswerKey===key?'selected':''}">${esc(label)}</button>`).join('')}</div><footer>Sample assistant · responses are predefined for this prototype</footer></section>`:''}<button type="button" class="assistant-launcher" data-action="assistant-toggle" aria-expanded="${assistantOpen}" aria-controls="assistant-panel"><span class="assistant-launcher-mark" aria-hidden="true">P</span><span>${assistantOpen?'Close assistant':'Ask PRAMAN'}</span></button></div>`}
function shell(content){
 const active=location.pathname;
 const navTitle=NAV.find(x=>x[1]===active)?.[0];
 const title=navTitle||(active.startsWith('/app/fdrs/')?'FDR detail':active.startsWith('/app/releases/')?'Release detail':'Praman');
 const rolePaths={'Institution User':['/app/overview','/app/fdrs','/app/submit','/app/maturities','/app/releases','/app/settings'],'Regional Officer':['/app/overview','/app/fdrs','/app/scrutiny','/app/verification','/app/maturities','/app/releases','/app/audit','/app/settings'],'AICTE Officer':NAV.map(x=>x[1]),'Bank Verifier':['/app/overview','/app/verification','/app/releases','/app/settings']};
 const allowed=NAV.filter(x=>rolePaths[role]?.includes(x[1]));
 return `<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="/app/overview" data-nav="/app/overview"><span class="praman-glyph" aria-hidden="true">P</span>PRAMAN</a><div class="nav-label">Workspace</div><nav class="side-nav">${allowed.map(([name,path,icon])=>`<a class="nav-link ${active===path||active.startsWith(`${path}/`)?'active':''}" href="${path}" data-nav="${path}"><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</a>`).join('')}</nav><div class="sidebar-bottom"><p class="role-caption">Current workspace</p><select class="role-select" id="role-switch" aria-label="Switch sample workspace">${ROLE_OPTIONS.map(x=>`<option value="${x}" ${x===role?'selected':''}>${x}</option>`).join('')}</select>${role==='AICTE Officer'?'<button class="btn quiet" style="width:100%;margin-top:7px" data-action="reset-confirm">Reset case records</button>':''}</div></aside><button class="mobile-nav-backdrop" type="button" data-action="menu" aria-label="Close navigation"></button><div class="main-shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="false" aria-controls="sidebar"><span class="menu-bars" aria-hidden="true"></span></button><span class="crumb">${esc(title)}</span></div><div class="topbar-right"><span class="demo-chip">SAMPLE WORKSPACE</span><span class="role-chip">${esc(role)}</span><button class="icon-btn theme-toggle" data-action="theme" aria-label="Toggle light and dark theme" title="Toggle theme">Aa</button></div></header><main class="main-content">${content}</main></div></div>${floatingAssistant()}<div id="modal-root"></div>`
}
function render(){const auditHead=state.audit[0]?.id||null;const auditUpdated=Boolean(lastRenderedAuditEvent&&auditHead&&auditHead!==lastRenderedAuditEvent);lastRenderedAuditEvent=auditHead;const p=page();let html;if(p==='/')html=landing();else if(p==='/login')html=authPage();else if(p==='/demo')html=demoEntry();else if(p==='/app/overview')html=shell(role==='Bank Verifier'?verificationPage():`${overview()}${role==='AICTE Officer'?releaseRadar():''}`);else if(p==='/app/reconciliation')html=shell(role==='AICTE Officer'?reconciliationPage():`${pageHead('Reconciliation unavailable','Reconciliation is available to the AICTE Officer role.')}${link('/app/overview','Return to overview','btn')}`);else if(p==='/app/fdrs')html=shell(role==='Bank Verifier'?`${pageHead('Register unavailable','Bank Verifier access is limited to assigned requests.')}${link('/app/verification','Open verification queue →','btn')}`:register());else if(p.startsWith('/app/fdrs/')){const f=getFdr(decodeURIComponent(p.split('/').pop()));const allowed=f&&canAccessFdr(f)&&role!=='Bank Verifier';html=shell(allowed?detail(f.id):`${pageHead('Record unavailable','This role does not have access to this record in the demo.')}${link('/app/overview','Return to overview','btn')}`)}else if(p==='/app/submit')html=shell(role==='Institution User'?wizard():`${pageHead('Submission unavailable','FDR submission is available in the Institution User demo role.')}${link('/app/overview','Return to overview','btn')}`);else if(p==='/app/scrutiny')html=shell(['Regional Officer','AICTE Officer'].includes(role)?scrutiny():`${pageHead('Reviewer workspace','Scrutiny access is available in the AICTE Officer demo role.')}${link('/app/overview','Return to overview','btn')}`);else if(p==='/app/verification')html=shell(role==='Institution User'?`${pageHead('Verification status','Your assigned FDR status is shown from the instrument record.')}${link('/app/fdrs','View my FDRs →','btn')}`:verificationPage());else if(p==='/app/maturities')html=shell(role==='Bank Verifier'?`${pageHead('Maturity view unavailable','Bank Verifier access is limited to assigned requests.')}${link('/app/verification','Open verification queue →','btn')}`:maturities());else if(p==='/app/releases')html=shell(role==='Bank Verifier'?bankExecutionPage():releaseList());else if(p.startsWith('/app/releases/')){const rel=state.releases.find(x=>x.id===decodeURIComponent(p.split('/').pop()));html=shell(role!=='Bank Verifier'&&canAccessRelease(rel)?releaseDetail(rel.id):`${pageHead('Release case unavailable','This case is outside your assigned scope.')}${link('/app/overview','Return to overview','btn')}`)}else if(p==='/app/audit')html=shell(['Institution User','Regional Officer','AICTE Officer'].includes(role)?auditPage():`${pageHead('Audit Trail','The cross-institution audit trail is available to the AICTE Officer demo role.')}${link('/app/overview','Return to overview','btn')}`);else if(p==='/app/policy')html=shell(role==='AICTE Officer'?policyPage():`${pageHead('Policy & Rules','This reference is available in the AICTE Officer demo role.')}${link('/app/overview','Return to overview','btn')}`);else if(p==='/app/settings')html=shell(settingsPage());else html=`<main class="demo-entry"><h1>Page not found</h1>${link('/','Return home','btn')}</main>`;document.querySelector('#app').innerHTML=routeTransition?'<div class="route-enter">'+html+'</div>':auditUpdated?'<div class="state-update">'+html+'</div>':html;cleanVisibleCopy(document.querySelector('#app'));document.title=`${p==='/'?'Praman':p==='/demo'?'Choose your role':p.split('/').pop().replaceAll('-',' ')} · Security Deposit Management`;const steps=document.querySelector('.steps');if(steps?.classList?.add){if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){steps.classList.add('is-visible')}else{steps.classList.add('motion-pending');const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){steps.classList.add('is-visible');observer.disconnect()}},{threshold:.18});observer.observe(steps)}}observeLandingSections()}
function cleanVisibleCopy(root){if(!root||typeof document.createTreeWalker!=='function'||typeof root.querySelectorAll!=='function')return;const clean=(value,preserveSynthetic=false)=>{let text=String(value).replace(/SAMPLE\s*\/\s*DEMO/gi,'SAMPLE').replace(/DEMO ENVIRONMENT/gi,'').replace(/Confirmed in demo data/gi,'Confirmed in sample data').replace(/demo data/gi,'sample data').replace(/demo samples?/gi,'sample').replace(/demo record/gi,'sample record').replace(/demo FDR/gi,'sample FDR').replace(/demo ledger/gi,'ledger').replace(/demo role/gi,'role').replace(/demo response/gi,'response').replace(/demo request/gi,'request').replace(/demo records?/gi,'records').replace(/demo fixture/gi,'sample fixture').replace(/demo clock/gi,'fixed clock').replace(/demo date/gi,'date').replace(/demo path/gi,'workflow').replace(/demo actions/gi,'actions').replace(/demo events/gi,'events').replace(/simulated officer workspace/gi,'Bank officer workspace').replace(/No data came from a bank system\./gi,'').replace(/demonstration convenience/gi,'').replace(/demonstration only/gi,'').replace(/\bsimulated bank officer\b/gi,'Bank officer');if(!preserveSynthetic)text=text.replace(/\bsynthetic\b/gi,'sample');return text.replace(/\bin demo\b/gi,'').replace(/\bdemo\b/gi,'').replace(/[ \t]{2,}/g,' ').replace(/\s+([,.;:])/g,'$1').trim()};const walker=document.createTreeWalker(root,4);while(walker.nextNode()){const node=walker.currentNode;const preserve=Boolean(node.parentElement?.closest('[data-preserve-demo-copy]'));node.nodeValue=preserve?(node.nodeValue||''):clean(node.nodeValue||'',Boolean(node.parentElement?.closest('[data-preserve-synthetic]')))}for(const el of root.querySelectorAll('[aria-label],[title],[placeholder]'))if(!el.closest('[data-preserve-demo-copy]'))for(const name of ['aria-label','title','placeholder'])if(el.hasAttribute(name))el.setAttribute(name,clean(el.getAttribute(name)));root.querySelectorAll('.demo-chip:not([data-preserve-demo-copy]),.env-label,.hero-note').forEach(el=>el.remove());root.querySelectorAll('.field-row').forEach(el=>{if(el.querySelector('span')?.textContent.trim()==='Environment')el.remove()});root.querySelectorAll('.notice:not([data-preserve-demo-copy]),.callout:not([data-preserve-demo-copy]),.small:not([data-preserve-demo-copy])').forEach(el=>{if(/demo boundary|data only.*no live bank connection|browser-local history.*production audit log|all figures and events shown are|no live bank connection|bank officer role is a demonstration boundary/i.test(el.textContent||''))el.remove()})}
function cleanVisibleCopyText(value){return String(value).replace(/demo data/gi,'sample data').replace(/demo role/gi,'role').replace(/demo response/gi,'response').replace(/\bsimulated bank officer\b/gi,'Bank officer').replace(/\bdemo\b/gi,'').replace(/\s{2,}/g,' ').trim()}
function observeLandingSections(){if(typeof document.querySelectorAll!=='function')return;const sections=document.querySelectorAll('[data-landing-reveal]');if(!sections.length)return;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(!('IntersectionObserver' in window)||reduced){sections.forEach(section=>section.classList.add('is-visible'));return}sections.forEach(section=>section.classList.add('reveal-pending'));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.16});sections.forEach(section=>observer.observe(section))}
function toast(msg){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.append(el)}el.textContent=cleanVisibleCopyText(msg);el.classList.remove('is-leaving');clearTimeout(toastTimer);clearTimeout(toastRemovalTimer);toastTimer=setTimeout(()=>{el.classList.add('is-leaving');toastRemovalTimer=setTimeout(()=>el.remove(),150)},3200)}
function modal(title,body,confirmText,callback,{danger=false}={}){const root=document.querySelector('#modal-root')||document.body;root.innerHTML=`<div class="overlay" role="presentation"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${esc(title)}</h2><p>${body}</p><form id="dialog-form"><div class="form-field"><label for="dialog-note">Reason / note</label><textarea id="dialog-note" name="note" placeholder="Add a short reason for the audit record"></textarea></div><div class="action-row" style="justify-content:flex-end"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn ${danger?'danger':'primary'}">${esc(confirmText)}</button></div></form></section></div>`;cleanVisibleCopy(root);root.querySelector('#dialog-note')?.focus();root.querySelector('#dialog-form').addEventListener('submit',e=>{e.preventDefault();const note=new FormData(e.currentTarget).get('note')||'';const submit=e.currentTarget.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;root.querySelector('.overlay')?.classList.add('is-closing');window.setTimeout(()=>{root.innerHTML='';callback(String(note))},140)})}
function captureWizard(){const form=document.querySelector('#wizard-form');if(!form)return;for(const [k,v] of new FormData(form).entries())if(typeof v==='string')wizardData[k]=v;if(wizardStep===1)wizardData.institution=wizardData.institution||'Aarohan Institute of Technology'}
async function action(button){const a=button.dataset.action,id=button.dataset.id;
if(a==='auth-mode'){authMode=button.dataset.mode==='signup'?'signup':'login';render();document.querySelector(authMode==='signup'?'#auth-signup-identity':'#auth-identity')?.focus();return}
if(a==='password-visibility'){const field=document.querySelector('#auth-password');if(field){const shown=field.type==='password';field.type=shown?'text':'password';button.textContent=shown?'Hide':'Show';button.setAttribute('aria-label',shown?'Hide password':'Show password');button.setAttribute('aria-pressed',String(shown))}return}
if(a==='forgot-password'){const feedback=document.querySelector('#auth-error');if(feedback)feedback.textContent='Password recovery is unavailable. Contact your administrator.';return}
if(a==='continue-demo'){button.disabled=true;button.innerHTML='<span class="loading-spinner" aria-hidden="true"></span> Opening demo';window.setTimeout(()=>navigate('/demo'),120);return}
if(a==='theme'){document.documentElement.classList.toggle('dark');try{localStorage.setItem('praman-demo-theme',document.documentElement.classList.contains('dark')?'dark':'light')}catch{}return}
if(a==='menu'){const sidebar=document.querySelector('#sidebar');const open=sidebar?.classList.toggle('open')||false;document.querySelector('.mobile-menu')?.setAttribute('aria-expanded',String(open));return}
if(a==='assistant-toggle'){assistantOpen=!assistantOpen;render();document.querySelector(assistantOpen?'.assistant-close':'.assistant-launcher')?.focus();return}
if(a==='assistant-close'){assistantOpen=false;render();document.querySelector('.assistant-launcher')?.focus();return}
if(a==='assistant-choice'){assistantAnswerKey=['attention','mismatch','release'].includes(button.dataset.choice)?button.dataset.choice:'attention';assistantOpen=true;render();document.querySelector('.assistant-choices button.selected')?.focus();return}
if(a==='close-modal'){const overlay=document.querySelector('#modal-root .overlay');overlay?.classList.add('is-closing');window.setTimeout(()=>{document.querySelector('#modal-root').innerHTML=''},140);return}
if(a==='clear-filters'||a==='clear-scrutiny'||a==='clear-audit'){navigate(location.pathname);return}
if(a==='chat-prompt'){const form=document.querySelector('#policy-assistant'),input=form?.elements?.question;if(input){input.value=button.dataset.prompt||'';form.requestSubmit()}return}
if(a==='sample-document'){wizardData.sample=true;render();return}
 if(a==='run-reconciliation'){if(service.reconcile()){render();toast('demo ledger reconciliation completed')}return}
 if(a==='daily-sweep'){const n=service.dailySweep();render();toast(`${n} new monitoring escalation${n===1?'':'s'} recorded`);return}
 if(a==='replace-document'){if(service.simulateReplacement(id)){render();toast('New sample document version fingerprinted; prior evidence retained')}return}
if(a==='wizard-prev'){captureWizard();wizardStep=Math.max(1,wizardStep-1);render();return}
if(a==='reset-confirm'){if(role!=='AICTE Officer'){toast('Only an AICTE Officer can reset shared records');return}modal('Reset demo data?','This restores the documented demo seed records and clears local demo changes in this browser. This action cannot be undone.','Reset data',()=>{service.reset();navigate('/app/overview');toast('Demo data restored to seed state')},{danger:true});return}
 if(a==='request-verification'){if(!['Regional Officer','AICTE Officer'].includes(role)){toast('Switch to the AICTE Officer demo role to create a request');return}if(await service.requestVerification(id)){render();toast('Simulated verification request created')}else toast('A pending request already exists or the record is unavailable');return}
if(a==='resolve-finding'){modal(button.dataset.state==='Correction requested'?'Request a correction':'Record reviewer disposition','Add the reason for this reviewer action. The finding remains visible in the record history.','Save disposition',note=>{if(!note.trim()){toast('Add a reason before recording this action');return}service.disposition(id,button.dataset.state,note);render();toast('Reviewer disposition recorded')});return}
if(a==='request-release'){if(role!=='Institution User'){toast('Only the Institution User can submit a release review request');return}modal('Request release review','The request enters configured review gates. It does not authorize lien release or move funds.','Submit request',note=>{if(!note.trim()){toast('Add a reason for this request');return}const result=service.requestRelease(id,note);if(result){render();toast('Release review request submitted')}else toast('A release case already exists or this record is unavailable')});return}
if(a==='bank-response'){if(role!=='Bank Verifier'){toast('Switch to Bank Verifier to respond');return}modal(`Submit response: ${button.dataset.outcome}`,'This will append demo response evidence and update the linked FDR in the demo. No live bank connection is used.','Submit simulated response',note=>{if(service.bankResponse(id,button.dataset.outcome,note)){render();toast('Simulated response recorded')}else toast('This request is no longer pending')});return}
if(a==='record-renewal'){if(!['Institution User','Regional Officer','AICTE Officer'].includes(role)){toast('This role cannot submit renewal or replacement records');return}const f=getFdr(id);if(f?.successor){toast(`Successor ${getFdr(f.successor)?.reference||'record'} is already linked`);return}modal('Record a successor FDR',`Create a linked demo successor for ${esc(f?.reference||'this record')}. The predecessor remains unresolved until evidence and clearances are reviewed.`,'Create successor',note=>{if(!note.trim()){toast('Add a short renewal evidence note');return}const successor=service.renewal(id,{reference:`FDR/26/${String(Date.now()).slice(-4)}`,amount:f.amount,declaredAmount:f.amount,institution:f.institution,programme:f.programme,bank:f.bank,branch:f.branch,ifsc:f.ifsc,holder:f.holder,maturity:'2029-10-25',lien:f.lien,renewalEvidence:note});if(successor){render();toast(`Successor ${successor.reference} linked`)}else toast('A successor is already linked or this role cannot record one')});return}
if(a==='complete-clearance'){const index=Number(button.dataset.index);modal('Record demo clearance','Enter a reason or evidence reference for this scenario clearance. This is not an official approval.','Record clearance',note=>{if(!note.trim()){toast('A reason is required');return}if(service.clearance(id,index,note)){render();toast('Demo clearance recorded')}else toast('Clearance could not be changed')});return}
if(a==='checker-approval'){modal('Record second reviewer decision','All configured demo clearances are complete. Record a second reviewer demo decision; this does not authorize an actual release.','Record demo decision',note=>{if(!note.trim()){toast('A decision note is required');return}if(service.checker(id,note)){render();toast('Demo checker decision recorded')}else toast('Case is not ready for this step')});return}
 if(a==='bank-execute'){modal('Record simulated bank response','This records a demo response after demo approval. No lien is changed and no funds move.','Record simulated confirmation',note=>{if(!note.trim()){toast('Add the response note');return}if(service.bankExecute(id,note)){render();toast('Simulated bank confirmation recorded')}else toast('This case is not awaiting simulated bank execution')});return}
if(a==='maker-recommendation'){modal('Record maker recommendation','Record a recommendation for second reviewer inspection. This is a simulated state and does not approve an actual release.','Record recommendation',note=>{if(!note.trim()){toast('A recommendation note is required');return}if(service.recommend(id,note)){render();toast('Demo recommendation recorded')}else toast('Case is not ready for recommendation')});return}
 if(a==='wizard-submit'){captureWizard();const data={...wizardData,amount:wizardData.extractedAmount||wizardData.amount,declaredAmount:wizardData.amount};const f=service.submit(data);if(!f){toast('Submission is only available in the Institution User role');return}wizardStep=1;wizardData={};navigate(`/app/fdrs/${f.id}`);toast(`Submitted ${f.reference} to demo scrutiny`);return}
}
document.addEventListener('click',e=>{if(e.target.closest('.mobile-nav-backdrop')){action(e.target.closest('.mobile-nav-backdrop'));return}const anchor=e.target.closest('a[data-nav]');if(anchor){e.preventDefault();const destination=anchor.dataset.nav;if(location.pathname==='/'&&destination==='/login'){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){navigate(destination);return}const landingRoot=document.querySelector('.landing');if(landingRoot?.classList.contains('is-leaving'))return;landingRoot?.classList.add('is-leaving');window.setTimeout(()=>navigate(destination),170);return}navigate(destination);return}const btn=e.target.closest('button[data-action]');if(btn){e.preventDefault();action(btn);return}const row=e.target.closest('tr[data-row]');if(row&&!e.target.closest('a,button,select,input'))navigate(row.dataset.row)});
document.addEventListener('change',e=>{if(e.target.name==='remember'){const feedback=document.querySelector('#auth-error');if(feedback)feedback.textContent=''}if(e.target.id==='role-switch'){if(ROLE_OPTIONS.includes(e.target.value)){role=e.target.value;save();render();toast(`Demo role changed to ${role}`)}}if(e.target.id==='reviewer-identity'){reviewerIdentity=e.target.value;render()}if(e.target.matches('input[type="file"][name="document"]')){wizardData.documentName=e.target.files?.[0]?.name||'';wizardData.sample=false;render()}});
document.addEventListener('submit',e=>{const form=e.target;if(form.id==='correction-response-form'){e.preventDefault();const data=Object.fromEntries(new FormData(form).entries());if(service.respondToCorrection(form.dataset.id,data)){render();toast('Updated details sent for reviewer follow-up')}else toast('This correction request is unavailable to the current role');return}if(form.id==='auth-login-form'){e.preventDefault();const data=new FormData(form),identity=String(data.get('identity')||'').trim(),password=String(data.get('password')||'');const feedback=form.querySelector('#auth-error');if(!identity||!password){feedback.textContent='Enter both your email or username and password to continue.';return}feedback.textContent='';navigate('/app/overview');return}if(form.id==='auth-signup-form'){e.preventDefault();const data=new FormData(form),identity=String(data.get('identity')||'').trim(),password=String(data.get('password')||''),confirm=String(data.get('confirmPassword')||''),feedback=form.querySelector('#auth-error');if(!identity){feedback.textContent='Enter an email or username.';return}if(password.length<8){feedback.textContent='Use at least 8 characters.';return}if(password!==confirm){feedback.textContent='The passwords do not match.';return}feedback.textContent='Account creation is unavailable. Contact your administrator.';return}if(form.id==='role-entry'){ e.preventDefault();const selected=String(new FormData(form).get('role')||'');if(!ROLE_OPTIONS.includes(selected))return;role=selected;save();navigate(role==='Bank Verifier'?'/app/verification':'/app/overview');return}
if(form.id==='register-filter'||form.id==='scrutiny-filter'||form.id==='audit-filter'||form.id==='maturity-filter'){e.preventDefault();const query=new URLSearchParams(new FormData(form));for(const [k,v] of [...query.entries()])if(!v)query.delete(k);navigate(`${location.pathname}${query.size?'?'+query.toString():''}`);return}
 if(form.id==='policy-assistant'){e.preventDefault();const question=String(new FormData(form).get('question')||'').trim();state.policyAnswer=policyAssistantAnswer(question);save();render();document.querySelector('.chat-message.assistant:last-child')?.scrollIntoView({block:'nearest'});return}
if(form.id==='wizard-form'){e.preventDefault();captureWizard();let error='';if(wizardStep===1&&(!wizardData.institution||!wizardData.programme))error='Enter the institution and programme.';if(wizardStep===2){if(!wizardData.reference||!wizardData.bank||!wizardData.branch||Number(wizardData.amount)<=0)error='Complete the required FDR details.';else if(wizardData.maturity<=wizardData.issue)error='Maturity date must be after the issue date.'}if(wizardStep===3&&!wizardData.sample&&!wizardData.documentName)error='Choose a file or select the demo sample document.';if(wizardStep===4&&Number(wizardData.extractedAmount)<=0)error='Enter a positive illustrative extracted amount.';if(error){document.querySelector('#wizard-error').textContent=error;return}wizardStep=Math.min(6,wizardStep+1);render()}});
window.addEventListener('popstate',()=>{routeTransition=true;render();routeTransition=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(assistantOpen){assistantOpen=false;render();document.querySelector('.assistant-launcher')?.focus();return}const overlay=document.querySelector('#modal-root .overlay');if(overlay){overlay.classList.add('is-closing');window.setTimeout(()=>{document.querySelector('#modal-root').innerHTML=''},140)}const sidebar=document.querySelector('#sidebar');if(sidebar?.classList.contains('open')){sidebar.classList.remove('open');document.querySelector('.mobile-menu')?.setAttribute('aria-expanded','false');document.querySelector('.mobile-menu')?.focus()}}});
 try{if(localStorage.getItem('praman-demo-theme')==='dark')document.documentElement.classList.add('dark')}catch{}
 if(location.pathname==='/login')history.replaceState({},'', '/app/overview');
 cleanVisibleCopy=(root)=>{if(!root||typeof document.createTreeWalker!=='function')return;const natural=(value)=>String(value)
  .replace(/DEMO ENVIRONMENT\s*·\s*SYNTHETIC DATA/gi,'PROTOTYPE WORKSPACE')
  .replace(/DEMO ROLE SELECTOR\s*·\s*SYNTHETIC DATA/gi,'CHOOSE A WORKSPACE')
  .replace(/DEMO ROLE SWITCHER/gi,'WORKSPACE VIEW')
  .replace(/SYNTHETIC EXAMPLE/gi,'CASE EXAMPLE')
  .replace(/All records are synthetic/gi,'Interactive prototype')
  .replace(/synthetic records?/gi,'seeded case records')
  .replace(/synthetic data/gi,'sample records')
  .replace(/Open judge demo/gi,'Open judge workspace')
  .replace(/SIMULATED ASSISTANT/gi,'POLICY ASSISTANT')
  .replace(/Four hardcoded evidence-grounded responses\s*·\s*no external model\s*·\s*no legal or regulatory decision/gi,'Evidence-grounded guidance from the current case and policy context · official review required')
  .replace(/Evidence assistant\s*·\s*simulated/gi,'Evidence assistant')
  .replace(/Submitted simulated response/gi,'Bank response recorded')
  .replace(/simulated request/gi,'verification request')
  .replace(/Awaiting bank response\s*·\s*prototype/gi,'Awaiting bank response')
  .replace(/\bjudge\b/gi,'sample')
  .replace(/Fixed demo date/gi,'Reference date')
  .replace(/demo institutions/gi,'participating institutions')
  .replace(/demo role/gi,'workspace')
  .replace(/demo data/gi,'case records')
  .replace(/demo fixture/gi,'policy fixture')
  .replace(/demo bank-side/gi,'bank-side prototype')
  .replace(/demo bank/gi,'bank prototype')
  .replace(/simulated bank response/gi,'bank response · prototype')
  .replace(/demo response/gi,'prototype response')
  .replace(/demo records?/gi,'case records')
  .replace(/demo scenario/gi,'case workflow')
  .replace(/demo ledger/gi,'reference ledger')
  .replace(/demo request/gi,'verification request')
  .replace(/demo workflow/gi,'prototype workflow')
  .replace(/demo scrutiny/gi,'scrutiny queue')
  .replace(/demo actions/gi,'recorded actions')
  .replace(/demo events/gi,'recorded events')
  .replace(/demo sample/gi,'sample')
  .replace(/SAMPLE\s*\/\s*DEMO/gi,'SAMPLE')
  .replace(/\bin demo\b/gi,'in the prototype')
  .replace(/\bdemo\b/gi,'prototype')
  .replace(/\bsynthetic\b/gi,'sample')
  .replace(/[ \t]{2,}/g,' ')
  .replace(/\s+([,.;:])/g,'$1')
  .trim();const walker=document.createTreeWalker(root,4);while(walker.nextNode())walker.currentNode.nodeValue=natural(walker.currentNode.nodeValue||'');for(const el of root.querySelectorAll('[aria-label],[title],[placeholder]'))for(const name of ['aria-label','title','placeholder'])if(el.hasAttribute(name))el.setAttribute(name,natural(el.getAttribute(name)))};
 ensureFingerprints();render();
